WITH chart_input AS (FROM penguins |> WHERE body_mass_g IS NOT NULL) FROM chart_input |> AGGREGATE count(*) AS penguins |> AS aggregates |> LEFT OUTER JOIN (FROM chart_input |> EXTEND bin(body_mass_g) OVER () AS body_mass_g_bin |> AGGREGATE count(*) AS n GROUP BY body_mass_g_bin |> AGGREGATE bar(x => scaled(body_mass_g_bin, title => 'body_mass_g'), y => scaled(n, title => 'count(*)')) AS chart) AS charts ON true |> SELECT charts.chart, aggregates.penguins
